import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S01/S01E07.html","title":"S01E07 The One with the Blackout","lang":"zh-CN","frontmatter":{"title":"S01E07 The One with the Blackout","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":7},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":29.25,"words":8775},"filePathRelative":"语言/英语/Friends老友记/S01/S01E07.md"}`),l={name:`S01E07.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=a(`h1`,{id:`the-one-with-the-blackout`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#the-one-with-the-blackout`},[a(`span`,null,`The One with the Blackout`)])],-1),c[1]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`停电的那个`)])],-1),c[2]||=a(`hr`,null,null,-1),c[3]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Rachel is introducing Phoebe, who is playing her guitar for the crowd.`)],-1),c[4]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，瑞秋正在介绍菲比，菲比正在为观众弹吉他。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/001.mp3`}),c[5]||=i(),c[6]||=a(`strong`,null,`Rachel Green:`,-1),c[7]||=i(` Everybody? Shh, shhh. Uhhh... Central Perk is proud to present the music of Miss Phoebe Buffay.`,-1),c[8]||=a(`blockquote`,null,[a(`p`,null,`每个人？嘘，嘘。嗯……Central Perk很荣幸为您呈现菲比·布菲小姐的音乐。`)],-1),c[9]||=a(`p`,null,[a(`em`,null,`(applause)`)],-1),c[10]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（掌声）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/002.mp3`}),c[11]||=i(),c[12]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[13]||=i(` Hi. Um, I want to start with a song thats about that moment when you suddenly realize what life is all about. OK, here we go. (plays a chord, then the lights go out) OK, thank you very much.`,-1),c[14]||=a(`blockquote`,null,[a(`p`,null,`嗨。嗯，我想从一首歌开始，这首歌是关于当你突然意识到生活是什么的那一刻。好了，开始吧。（弹奏和弦，然后灯光熄灭）好的，非常感谢。`)],-1),c[15]||=a(`hr`,null,null,-1),c[16]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The ATM vestibule of a bank, Chandler is inside. The lights go out, and he realizes he is trapped inside.`)],-1),c[17]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒在一家银行的自动取款机前厅内。灯光熄灭，他意识到自己被困在里面。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/003.mp3`}),c[18]||=t(` <strong>Chandler Bing:</strong> Oh, great. This is just...<blockquote><p>哦，太好了。这只是……</p></blockquote><p><em>(Chandler sees that there is a gorgeous model inside the vestibule with him. He makes a gesture of quiet exuberance.)</em></p><blockquote><p><em>（钱德勒看到前厅里有一个漂亮的模特和他在一起。他做了一个安静而兴高采烈的手势。）</em></p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Monica is on the phone with her mother. Phoebe, Rachel, and Ross are there.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，莫妮卡正在和她妈妈通电话。菲比、瑞秋和罗斯在那里。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S01/S01E07/004.mp3`}),c[19]||=i(),c[20]||=a(`strong`,null,`Rachel Green:`,-1),c[21]||=i(` Wow, this is so cool, you guys. The entire city is blacked out!`,-1),c[22]||=a(`blockquote`,null,[a(`p`,null,`哇，这太酷了，伙计们。整个城市都停电了！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/005.mp3`}),c[23]||=i(),c[24]||=a(`strong`,null,`Monica Geller:`,-1),c[25]||=i(` Mom says it's all of Manhattan, parts of Brooklyn and Queens, and they have no idea when it's coming back on.`,-1),c[26]||=a(`blockquote`,null,[a(`p`,null,`妈妈说是整个曼哈顿，布鲁克林和皇后区的一部分，他们不知道什么时候会重播。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/006.mp3`}),c[27]||=i(),c[28]||=a(`strong`,null,`Rachel Green:`,-1),c[29]||=i(` Wow, you guys, this is big.`,-1),c[30]||=a(`blockquote`,null,[a(`p`,null,`哇，你们这些家伙，这太大了。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/007.mp3`}),c[31]||=i(),c[32]||=a(`strong`,null,`Monica Geller:`,-1),c[33]||=i(` (into phone) Pants and a sweater? Why, mom? Who am I gonna meet in a blackout? Power company guys? Eligible looters? Could we talk about this later? OK. (hangs up)`,-1),c[34]||=a(`blockquote`,null,[a(`p`,null,`（对着电话）裤子和毛衣？为什么，妈妈？停电时我会遇到谁？电力公司的人？合格的抢劫者？我们可以晚点再谈吗？好啊（挂断电话）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/008.mp3`}),c[35]||=i(),c[36]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[37]||=i(` Can I borrow the phone? I want to call my apartment and check on my grandma. (to Monica) What's my number?`,-1),c[38]||=a(`blockquote`,null,[a(`p`,null,`我能借用一下电话吗？我想打电话到我的公寓去看看我奶奶。（对莫妮卡）我的电话号码是多少？`)],-1),c[39]||=a(`p`,null,[a(`em`,null,`(Monica and Rachel look at Phoebe strangely.)`)],-1),c[40]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡和瑞秋奇怪地看着菲比。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/009.mp3`}),c[41]||=i(),c[42]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[43]||=i(` Well, I never call me.`,-1),c[44]||=a(`blockquote`,null,[a(`p`,null,`嗯，我从来没给我打过电话。`)],-1),c[45]||=a(`hr`,null,null,-1),c[46]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM vestibule, Jill Goodacre is on the cellular phone. Chandler's thoughts are in italics.`)],-1),c[47]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`自动取款机前厅，吉尔·古德克正在打手机。钱德勒的想法是斜体的。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/010.mp3`}),c[48]||=i(),c[49]||=a(`strong`,null,`Chandler Bing:`,-1),c[50]||=i(` Oh my God, it's that Victoria's Secret model. Something... something Goodacre.`,-1),c[51]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，是维多利亚的秘密模特。某物好的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/011.mp3`}),c[52]||=i(),c[53]||=a(`strong`,null,`Jill:`,-1),c[54]||=i(` (on phone) Hi Mom, it's Jill.`,-1),c[55]||=a(`blockquote`,null,[a(`p`,null,`（打电话）嗨，妈妈，我是吉尔。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/012.mp3`}),c[56]||=i(),c[57]||=a(`strong`,null,`Chandler Bing:`,-1),c[58]||=i(` She's right, it's Jill. Jill Goodacre. Oh my God. I am trapped in an ATM vestibule with Jill Goodacre! (pause) Is it a vestibule? Maybe it's an atrium. Oh, yeah, that is the part to focus on, you idiot!`,-1),c[59]||=a(`blockquote`,null,[a(`p`,null,`她说得对，是吉尔。吉尔·古达克。哦，我的上帝。我和吉尔·古达克被困在自动取款机的门厅里！（停顿）是门厅吗？也许是中庭。哦，是的，这才是重点，你这个白痴！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/013.mp3`}),c[60]||=i(),c[61]||=a(`strong`,null,`Jill:`,-1),c[62]||=i(` (on phone) Yeah, I'm fine. I'm just stuck at the bank, in an ATM vestibule.`,-1),c[63]||=a(`blockquote`,null,[a(`p`,null,`（在电话上）是的，我很好。我只是被困在银行的自动取款机门厅里。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/014.mp3`}),c[64]||=i(),c[65]||=a(`strong`,null,`Chandler Bing:`,-1),c[66]||=i(` Jill says vestibule... I'm going with vestibule.`,-1),c[67]||=a(`blockquote`,null,[a(`p`,null,`吉尔说前厅……我要去门厅。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/015.mp3`}),c[68]||=i(),c[69]||=a(`strong`,null,`Jill:`,-1),c[70]||=i(` (on phone) I'm fine. No, I'm not alone... I don't know, some guy.`,-1),c[71]||=a(`blockquote`,null,[a(`p`,null,`（打电话）我很好。不，我不是一个人……我不知道，某个人。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/016.mp3`}),c[72]||=t(` <strong>Chandler Bing:</strong> Oh! Some guy. Some guy. &#39;Hey Jill, I saw you with some guy last night. Yes, he was some guy.<blockquote><p>哦！某个人。某个人嘿，吉尔，我昨晚看见你和一个男人在一起。是的，他是某个人。</p></blockquote><p><em>(Chandler strides proudly across the vestibule and Jill stares at him.)</em></p><blockquote><p><em>（钱德勒骄傲地跨过门厅，吉尔盯着他。）</em></p></blockquote><hr><p>🎬 <em>Monica&#39;s apartment, Joey enters with a menorah, the candles lit.</em></p><blockquote><p>🎬 <em>莫妮卡的公寓，乔伊拿着烛台进来，蜡烛点着。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S01/S01E07/017.mp3`}),c[73]||=i(),c[74]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[75]||=i(` Hi everyone.`,-1),c[76]||=a(`blockquote`,null,[a(`p`,null,`大家好。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/018.mp3`}),c[77]||=i(),c[78]||=a(`strong`,null,`Ross Geller:`,-1),c[79]||=i(` And officiating at tonight's blackout, is Rabbi Tribbiani.`,-1),c[80]||=a(`blockquote`,null,[a(`p`,null,`今晚灯火管制的主礼嘉宾是拉比·特里比亚尼。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/019.mp3`}),c[81]||=i(),c[82]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[83]||=i(` Well, Chandler's old roomate was Jewish, and these are the only candles we have, so... Happy Chanukah, everyone.`,-1),c[84]||=a(`blockquote`,null,[a(`p`,null,`钱德勒的老室友是犹太人，我们只有这些蜡烛，所以……祝大家光明节快乐。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/020.mp3`}),c[85]||=i(),c[86]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[87]||=i(` (at window) Eww, look. Ugly Naked Guy lit a bunch of candles.`,-1),c[88]||=a(`blockquote`,null,[a(`p`,null,`（在窗口）哦，看。丑陋的裸男点燃了一束蜡烛。`)],-1),c[89]||=a(`p`,null,[a(`em`,null,`(They all look at the window, grossed out, then flinch in pain.)`)],-1),c[90]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们都看着窗户，感到恶心，然后痛苦地退缩。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/021.mp3`}),c[91]||=i(),c[92]||=a(`strong`,null,`Rachel Green:`,-1),c[93]||=i(` That had to hurt!`,-1),c[94]||=a(`blockquote`,null,[a(`p`,null,`那一定很痛！`)],-1),c[95]||=a(`hr`,null,null,-1),c[96]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM vestibule.`)],-1),c[97]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM前厅。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/022.mp3`}),c[98]||=i(),c[99]||=a(`strong`,null,`Chandler Bing:`,-1),c[100]||=i(` Alright, alright, alright. It's been fourteen and a half minutes and you still have not said one word. Oh God, do something. Just make contact, smile!`,-1),c[101]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，好吧。已经十四分钟半了，你一句话也没说。哦，上帝，做点什么。只要保持联系，微笑！`)],-1),c[102]||=a(`p`,null,[a(`em`,null,`(Chandler smiles at her, she smiles back sweetly.)`)],-1),c[103]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒朝她笑了笑，她也甜蜜地笑了笑。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/023.mp3`}),c[104]||=i(),c[105]||=a(`strong`,null,`Chandler Bing:`,-1),c[106]||=i(` There you go!`,-1),c[107]||=a(`blockquote`,null,[a(`p`,null,`给你！`)],-1),c[108]||=a(`p`,null,[a(`em`,null,`(He continues to smile like an idiot, and she looks frightened.)`)],-1),c[109]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他继续笑得像个白痴，而她看起来很害怕。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/024.mp3`}),c[110]||=i(),c[111]||=a(`strong`,null,`Chandler Bing:`,-1),c[112]||=i(` You're definitely scaring here.`,-1),c[113]||=a(`blockquote`,null,[a(`p`,null,`你在这里肯定吓坏了。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/025.mp3`}),c[114]||=i(),c[115]||=a(`strong`,null,`Jill:`,-1),c[116]||=i(` (awkwardly) Would you like to call somebody? (offering phone)`,-1),c[117]||=a(`blockquote`,null,[a(`p`,null,`（尴尬地）你想给别人打电话吗？（提供电话）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/026.mp3`}),c[118]||=i(),c[119]||=a(`strong`,null,`Chandler Bing:`,-1),c[120]||=i(` Yeah, about 300 guys I went to high school with. Yeah, thanks. (takes phone)`,-1),c[121]||=a(`blockquote`,null,[a(`p`,null,`是的，大约有300人和我一起上高中。是的，谢谢。（拿起电话）`)],-1),c[122]||=a(`hr`,null,null,-1),c[123]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, The phone rings; it's Chandler.`)],-1),c[124]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，电话铃响了，是钱德勒。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/027.mp3`}),c[125]||=i(),c[126]||=a(`strong`,null,`Monica Geller:`,-1),c[127]||=i(` Hello?`,-1),c[128]||=a(`blockquote`,null,[a(`p`,null,`喂？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/028.mp3`}),c[129]||=i(),c[130]||=a(`strong`,null,`Chandler Bing:`,-1),c[131]||=i(` Hey, it's me.`,-1),c[132]||=a(`blockquote`,null,[a(`p`,null,`嘿，是我。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/029.mp3`}),c[133]||=i(),c[134]||=a(`strong`,null,`Monica Geller:`,-1),c[135]||=i(` (to everyone) It's Chandler! (on phone) Are you OK?`,-1),c[136]||=a(`blockquote`,null,[a(`p`,null,`（对大家）是钱德勒！（电话）你还好吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/030.mp3`}),c[137]||=i(),c[138]||=a(`strong`,null,`Chandler Bing:`,-1),c[139]||=i(` Yeah, I'm fine. (trying to cover up what he is saying) I'm trppd in an ATM vstbl wth Jll Gdcr.`,-1),c[140]||=a(`blockquote`,null,[a(`p`,null,`是的，我很好。（试图掩盖他说的话）我在一台装有Jll Gdcr的ATM vstbl里。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/031.mp3`}),c[141]||=i(),c[142]||=a(`strong`,null,`Monica Geller:`,-1),c[143]||=i(` What?`,-1),c[144]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/032.mp3`}),c[145]||=i(),c[146]||=a(`strong`,null,`Chandler Bing:`,-1),c[147]||=i(` I'm trppd... in an ATM vstbl... wth Jll Gdcr!`,-1),c[148]||=a(`blockquote`,null,[a(`p`,null,`我是trppd……在ATM vstbl中……使用Jll Gdcr！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/033.mp3`}),c[149]||=i(),c[150]||=a(`strong`,null,`Monica Geller:`,-1),c[151]||=i(` I have no idea what you just said.`,-1),c[152]||=a(`blockquote`,null,[a(`p`,null,`我不知道你刚才说了什么。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/034.mp3`}),c[153]||=i(),c[154]||=a(`strong`,null,`Chandler Bing:`,-1),c[155]||=i(` (angry) Put Joey on the phone.`,-1),c[156]||=a(`blockquote`,null,[a(`p`,null,`（生气）让乔伊接电话。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/035.mp3`}),c[157]||=i(),c[158]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[159]||=i(` What's up man?`,-1),c[160]||=a(`blockquote`,null,[a(`p`,null,`怎么了，伙计？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/036.mp3`}),c[161]||=i(),c[162]||=a(`strong`,null,`Chandler Bing:`,-1),c[163]||=i(` I'm trppd... in an ATM vstbl... wth JLL GDCR.`,-1),c[164]||=a(`blockquote`,null,[a(`p`,null,`我是trppd……在ATM vstbl中……使用JLL GDCR。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/037.mp3`}),c[165]||=i(),c[166]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[167]||=i(` (to everyone) Oh my God! He's trapped in an ATM vestibule with Jill Goodacre! (on phone) Chandler, listen. (says something intentionally garbled)`,-1),c[168]||=a(`blockquote`,null,[a(`p`,null,`（对大家）哦，我的天啊！他和吉尔·古达克被困在自动取款机的门厅里！（电话中）钱德勒，听着。（故意乱说）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/038.mp3`}),c[169]||=i(),c[170]||=a(`strong`,null,`Chandler Bing:`,-1),c[171]||=i(` Yeah, like that thought never entered my mind.`,-1),c[172]||=a(`blockquote`,null,[a(`p`,null,`是啊，就像我从来没有想过那样。`)],-1),c[173]||=a(`hr`,null,null,-1),c[174]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, time has passed. The five are sitting around the coffee table talking.`)],-1),c[175]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，时间过去了。五个人围坐在咖啡桌旁聊天。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/039.mp3`}),c[176]||=i(),c[177]||=a(`strong`,null,`Rachel Green:`,-1),c[178]||=i(` Alright, somebody.`,-1),c[179]||=a(`blockquote`,null,[a(`p`,null,`好吧，找个人。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/040.mp3`}),c[180]||=i(),c[181]||=a(`strong`,null,`Monica Geller:`,-1),c[182]||=i(` OK, I'll go. OK, senior year of college... on a pool table.`,-1),c[183]||=a(`blockquote`,null,[a(`p`,null,`好的，我去。好的，大学四年级……在台球桌上。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/041.mp3`}),c[184]||=i(),c[185]||=a(`strong`,null,`All:`,-1),c[186]||=i(` Whoooaa!`,-1),c[187]||=a(`blockquote`,null,[a(`p`,null,`哇！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/042.mp3`}),c[188]||=i(),c[189]||=a(`strong`,null,`Ross Geller:`,-1),c[190]||=i(` That's my sister.`,-1),c[191]||=a(`blockquote`,null,[a(`p`,null,`那是我妹妹。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/043.mp3`}),c[192]||=i(),c[193]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[194]||=i(` OK... my weirdest place would have to be... the women's room on the second floor of the New York CIty public library.`,-1),c[195]||=a(`blockquote`,null,[a(`p`,null,`好的……我最奇怪的地方应该是……纽约市公共图书馆二楼的女厕所。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/044.mp3`}),c[196]||=i(),c[197]||=a(`strong`,null,`Monica Geller:`,-1),c[198]||=i(` Oh my God! What were you doing in a library?`,-1),c[199]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！你在图书馆干什么？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/045.mp3`}),c[200]||=i(),c[201]||=a(`strong`,null,`Ross Geller:`,-1),c[202]||=i(` Pheebs, what about you?`,-1),c[203]||=a(`blockquote`,null,[a(`p`,null,`菲比，你呢？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/046.mp3`}),c[204]||=i(),c[205]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[206]||=i(` Oh... Milwaukee.`,-1),c[207]||=a(`blockquote`,null,[a(`p`,null,`哦……密尔沃基。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/047.mp3`}),c[208]||=i(),c[209]||=a(`strong`,null,`Rachel Green:`,-1),c[210]||=i(` Um... Ross?`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`嗯……罗斯？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/048.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`Ross Geller:`,-1),c[214]||=i(` Disneyland, 1989, 'It's a Small World After All.'`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`迪斯尼乐园，1989年，“这毕竟是个小世界。”`)],-1),r(p,{src:`/audio/friends/S01/S01E07/049.mp3`}),c[216]||=i(),c[217]||=a(`strong`,null,`All:`,-1),c[218]||=i(` No way!`,-1),c[219]||=a(`blockquote`,null,[a(`p`,null,`不可能！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/050.mp3`}),c[220]||=i(),c[221]||=a(`strong`,null,`Ross Geller:`,-1),c[222]||=i(` The ride broke down. So, Carol and I went behind a couple of those mechanical Dutch children... then they fixed the ride, and we were asked never to return to the Magic Kingdom.`,-1),c[223]||=a(`blockquote`,null,[a(`p`,null,`车子坏了。所以，卡萝和我跟在几个机械荷兰孩子后面……然后他们修好了车，我们被要求永远不要回到魔法王国。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/051.mp3`}),c[224]||=i(),c[225]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[226]||=i(` Oh, Rachel.`,-1),c[227]||=a(`blockquote`,null,[a(`p`,null,`哦，瑞秋。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/052.mp3`}),c[228]||=i(),c[229]||=a(`strong`,null,`Rachel Green:`,-1),c[230]||=i(` Oh come on, I already went.`,-1),c[231]||=a(`blockquote`,null,[a(`p`,null,`哦，得了吧，我已经去了。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/053.mp3`}),c[232]||=i(),c[233]||=a(`strong`,null,`Monica Geller:`,-1),c[234]||=i(` You did not go!`,-1),c[235]||=a(`blockquote`,null,[a(`p`,null,`你没去！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/054.mp3`}),c[236]||=i(),c[237]||=a(`strong`,null,`All:`,-1),c[238]||=i(` Come on.`,-1),c[239]||=a(`blockquote`,null,[a(`p`,null,`来吧。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/055.mp3`}),c[240]||=i(),c[241]||=a(`strong`,null,`Rachel Green:`,-1),c[242]||=i(` Oh, alright. The weirdest place would have to be... (sigh)... oh, the foot of the bed.`,-1),c[243]||=a(`blockquote`,null,[a(`p`,null,`哦，好的。最奇怪的地方应该是……（叹气）……哦，床脚。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/056.mp3`}),c[244]||=i(),c[245]||=a(`strong`,null,`Ross Geller:`,-1),c[246]||=i(` Step back.`,-1),c[247]||=a(`blockquote`,null,[a(`p`,null,`退后一步。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/057.mp3`}),c[248]||=i(),c[249]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[250]||=i(` We have a winner!`,-1),c[251]||=a(`blockquote`,null,[a(`p`,null,`我们赢了！`)],-1),c[252]||=a(`p`,null,[i(`⏱ `),a(`em`,null,`Time lapse, Ross and Rachel are talking, Joey is on the couch, and Monica and Phoebe are out of the room.`)],-1),c[253]||=a(`blockquote`,null,[a(`p`,null,`[时间流逝，罗斯和瑞秋在聊天，乔伊在沙发上，莫妮卡和菲比不在房间。]`)],-1),r(p,{src:`/audio/friends/S01/S01E07/058.mp3`}),c[254]||=i(),c[255]||=a(`strong`,null,`Rachel Green:`,-1),c[256]||=i(` I just never had a relationship with that kind of passion, you know, where you have to have somebody right there, in the middle of a theme park.`,-1),c[257]||=a(`blockquote`,null,[a(`p`,null,`我从来没有和那种激情有过关系，你知道，在那里你必须有人在主题公园的中央。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/059.mp3`}),c[258]||=i(),c[259]||=a(`strong`,null,`Ross Geller:`,-1),c[260]||=i(` Well, it was the only thing to do there that didn't have a line.`,-1),c[261]||=a(`blockquote`,null,[a(`p`,null,`嗯，这是唯一一件没有台词的事。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/060.mp3`}),c[262]||=i(),c[263]||=a(`strong`,null,`Rachel Green:`,-1),c[264]||=i(` There, well, see? Barry wouldn't even kiss me on a miniature golf course.`,-1),c[265]||=a(`blockquote`,null,[a(`p`,null,`好了，看到了吗？巴里甚至不会在迷你高尔夫球场上吻我。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/061.mp3`}),c[266]||=i(),c[267]||=a(`strong`,null,`Ross Geller:`,-1),c[268]||=i(` Come on.`,-1),c[269]||=a(`blockquote`,null,[a(`p`,null,`来吧。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/062.mp3`}),c[270]||=i(),c[271]||=a(`strong`,null,`Rachel Green:`,-1),c[272]||=i(` No, he said we were holding up the people behind us.`,-1),c[273]||=a(`blockquote`,null,[a(`p`,null,`不，他说我们挡住了后面的人。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/063.mp3`}),c[274]||=i(),c[275]||=a(`strong`,null,`Ross Geller:`,-1),c[276]||=i(` (sarcastically) And you didn't marry him because...?`,-1),c[277]||=a(`blockquote`,null,[a(`p`,null,`（讽刺地）你没有嫁给他是因为……？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/064.mp3`}),c[278]||=i(),c[279]||=a(`strong`,null,`Rachel Green:`,-1),c[280]||=i(` I mean, do you think there are people who go through life never having that kind of...`,-1),c[281]||=a(`blockquote`,null,[a(`p`,null,`我的意思是，你认为有没有人一生中从来没有过那种……`)],-1),r(p,{src:`/audio/friends/S01/S01E07/065.mp3`}),c[282]||=i(),c[283]||=a(`strong`,null,`Ross Geller:`,-1),c[284]||=i(` Probably. But you know, I'll tell you something. Passion is way overrated.`,-1),c[285]||=a(`blockquote`,null,[a(`p`,null,`可能吧。但是你知道，我要告诉你一些事情。激情被高估了。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/066.mp3`}),c[286]||=i(),c[287]||=a(`strong`,null,`Rachel Green:`,-1),c[288]||=i(` Yeah right.`,-1),c[289]||=a(`blockquote`,null,[a(`p`,null,`对。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/067.mp3`}),c[290]||=i(),c[291]||=a(`strong`,null,`Ross Geller:`,-1),c[292]||=i(` It is. Eventually, it kind of... burns out. But hopefully, what you're left with is trust, and security, and... well, in the case of my ex-wife, lesbianism. So, you know, for all of those people who miss out on that passion... thing, there's all that other good stuff.`,-1),c[293]||=a(`blockquote`,null,[a(`p`,null,`是的。最终，它有点……烧坏了。但希望你剩下的是信任和安全，还有……我前妻是女同性恋。所以，你知道，对于那些错过激情的人……还有其他的好东西。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/068.mp3`}),c[294]||=i(),c[295]||=a(`strong`,null,`Rachel Green:`,-1),c[296]||=i(` (sigh) OK.`,-1),c[297]||=a(`blockquote`,null,[a(`p`,null,`（叹气）好的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/069.mp3`}),c[298]||=i(),c[299]||=a(`strong`,null,`Ross Geller:`,-1),c[300]||=i(` But, um... I don't think that's going to be you.`,-1),c[301]||=a(`blockquote`,null,[a(`p`,null,`但是，嗯……我不认为那会是你。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/070.mp3`}),c[302]||=i(),c[303]||=a(`strong`,null,`Rachel Green:`,-1),c[304]||=i(` You don't.`,-1),c[305]||=a(`blockquote`,null,[a(`p`,null,`你没有。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/071.mp3`}),c[306]||=i(),c[307]||=a(`strong`,null,`Ross Geller:`,-1),c[308]||=i(` Uh-uh. See, I see.... big passion in your future.`,-1),c[309]||=a(`blockquote`,null,[a(`p`,null,`嗯。看，我明白了……。对你的未来充满激情。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/072.mp3`}),c[310]||=i(),c[311]||=a(`strong`,null,`Rachel Green:`,-1),c[312]||=i(` Really?`,-1),c[313]||=a(`blockquote`,null,[a(`p`,null,`真的吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/073.mp3`}),c[314]||=i(),c[315]||=a(`strong`,null,`Ross Geller:`,-1),c[316]||=i(` Mmmm.`,-1),c[317]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/074.mp3`}),c[318]||=i(),c[319]||=a(`strong`,null,`Rachel Green:`,-1),c[320]||=i(` You do?`,-1),c[321]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/075.mp3`}),c[322]||=i(),c[323]||=a(`strong`,null,`Ross Geller:`,-1),c[324]||=i(` I do.`,-1),c[325]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/076.mp3`}),c[326]||=i(),c[327]||=a(`strong`,null,`Rachel Green:`,-1),c[328]||=i(` Oh Ross, you're so great. (she playfully rubs his head and gets up)`,-1),c[329]||=a(`blockquote`,null,[a(`p`,null,`哦，罗斯，你太棒了。（她顽皮地揉着他的头，站了起来）`)],-1),c[330]||=a(`p`,null,[a(`em`,null,`(Ross gets up, pleased with himself.)`)],-1),c[331]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯站起来，对自己很满意。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/077.mp3`}),c[332]||=i(),c[333]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[334]||=i(` It's never gonna happen.`,-1),c[335]||=a(`blockquote`,null,[a(`p`,null,`这永远不会发生。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/078.mp3`}),c[336]||=i(),c[337]||=a(`strong`,null,`Ross Geller:`,-1),c[338]||=i(` (innocently) What?`,-1),c[339]||=a(`blockquote`,null,[a(`p`,null,`（天真地）什么？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/079.mp3`}),c[340]||=i(),c[341]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[342]||=i(` You and Rachel.`,-1),c[343]||=a(`blockquote`,null,[a(`p`,null,`你和瑞秋。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/080.mp3`}),c[344]||=i(),c[345]||=a(`strong`,null,`Ross Geller:`,-1),c[346]||=i(` (acts surprised) What? (pause) Why not?`,-1),c[347]||=a(`blockquote`,null,[a(`p`,null,`（表现得很惊讶）什么？（停顿）为什么不呢？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/081.mp3`}),c[348]||=i(),c[349]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[350]||=i(` Because you waited too long to make your move, and now you're in the friend zone.`,-1),c[351]||=a(`blockquote`,null,[a(`p`,null,`因为你等了太久才采取行动，现在你在朋友区。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/082.mp3`}),c[352]||=i(),c[353]||=a(`strong`,null,`Ross Geller:`,-1),c[354]||=i(` No, no, no. I'm not in the zone.`,-1),c[355]||=a(`blockquote`,null,[a(`p`,null,`不，不，不。我不在这个区域。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/083.mp3`}),c[356]||=i(),c[357]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[358]||=i(` Ross, you're mayor of the zone.`,-1),c[359]||=a(`blockquote`,null,[a(`p`,null,`罗斯，你是这个区的市长。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/084.mp3`}),c[360]||=i(),c[361]||=a(`strong`,null,`Ross Geller:`,-1),c[362]||=i(` I'm taking my time, alright? I'm laying the groundwork. Yeah. I mean, every day I get just a little bit closer to...`,-1),c[363]||=a(`blockquote`,null,[a(`p`,null,`我慢慢来，好吗？我正在打基础。是 啊我是说，每天我都离……`)],-1),r(p,{src:`/audio/friends/S01/S01E07/085.mp3`}),c[364]||=i(),c[365]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[366]||=i(` Priesthood! Look Ross, I'm telling you, she has no idea what you're thinking. If you don't ask her out soon you're going to end up stuck in the zone forever.`,-1),c[367]||=a(`blockquote`,null,[a(`p`,null,`牧师身份！罗斯，我告诉你，她不知道你在想什么。如果你不尽快约她出去，你最终会永远陷入困境。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/086.mp3`}),c[368]||=i(),c[369]||=a(`strong`,null,`Ross Geller:`,-1),c[370]||=i(` I will, I will. See, I'm waiting for the right moment. (Joey looks at him) What? What, now?`,-1),c[371]||=a(`blockquote`,null,[a(`p`,null,`我会的，我会的。看，我在等待合适的时机。（乔伊看着他）什么？什么，现在？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/087.mp3`}),c[372]||=i(),c[373]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[374]||=i(` Yeeeeaaaahhh! What's messing you up? The wine? The candles? The moonlight? You've just got to go up to her and say, 'Rachel, I think that...' (Rachel comes into the room behind them)`,-1),c[375]||=a(`blockquote`,null,[a(`p`,null,`是啊！你怎么搞砸了？葡萄酒？蜡烛？月光？你只要走到她跟前说，‘瑞秋，我想……’（瑞秋走进他们后面的房间）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/088.mp3`}),c[376]||=i(),c[377]||=a(`strong`,null,`Ross Geller:`,-1),c[378]||=i(` Shhhh!`,-1),c[379]||=a(`blockquote`,null,[a(`p`,null,`嘘！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/089.mp3`}),c[380]||=i(),c[381]||=a(`strong`,null,`Rachel Green:`,-1),c[382]||=i(` What are you shushing?`,-1),c[383]||=a(`blockquote`,null,[a(`p`,null,`你在嘘什么？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/090.mp3`}),c[384]||=i(),c[385]||=a(`strong`,null,`Ross Geller:`,-1),c[386]||=i(` We're shushing... because... we're trying to hear something. Listen. (everyone is silent) Don't you hear that?`,-1),c[387]||=a(`blockquote`,null,[a(`p`,null,`我们在嘘……因为……我们想听听什么。听（大家都沉默了）你没听见吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/091.mp3`}),c[388]||=i(),c[389]||=a(`strong`,null,`Rachel Green:`,-1),c[390]||=i(` Ahhhh!`,-1),c[391]||=a(`blockquote`,null,[a(`p`,null,`啊！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/092.mp3`}),c[392]||=i(),c[393]||=a(`strong`,null,`Ross Geller:`,-1),c[394]||=i(` See?`,-1),c[395]||=a(`blockquote`,null,[a(`p`,null,`看到了吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/093.mp3`}),c[396]||=i(),c[397]||=a(`strong`,null,`Rachel Green:`,-1),c[398]||=i(` Huh. (she agrees, but looks very confused)`,-1),c[399]||=a(`blockquote`,null,[a(`p`,null,`嗯。（她同意，但看起来很困惑）`)],-1),c[400]||=a(`hr`,null,null,-1),c[401]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM vestibule.`)],-1),c[402]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM前厅。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/094.mp3`}),c[403]||=i(),c[404]||=a(`strong`,null,`Jill:`,-1),c[405]||=i(` Would you like some gum?`,-1),c[406]||=a(`blockquote`,null,[a(`p`,null,`你要口香糖吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/095.mp3`}),c[407]||=i(),c[408]||=a(`strong`,null,`Chandler Bing:`,-1),c[409]||=i(` Um, is it sugarless?`,-1),c[410]||=a(`blockquote`,null,[a(`p`,null,`嗯，是无糖的吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/096.mp3`}),c[411]||=i(),c[412]||=a(`strong`,null,`Jill:`,-1),c[413]||=i(` (checks) Sorry, it's not.`,-1),c[414]||=a(`blockquote`,null,[a(`p`,null,`（检查）对不起，不是。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/097.mp3`}),c[415]||=i(),c[416]||=a(`strong`,null,`Chandler Bing:`,-1),c[417]||=i(` Oh, then no thanks. What the hell was that? Mental note: If Jill Goodacre offers you gum, you take it. If she offers you mangled animal carcass, you take it.`,-1),c[418]||=a(`blockquote`,null,[a(`p`,null,`哦，那就不用了，谢谢。那到底是什么？心理提示：如果吉尔·古德克给你口香糖，你就吃。如果她给你的是被弄坏的动物尸体，你就拿走。`)],-1),c[419]||=a(`hr`,null,null,-1),c[420]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica's apartment, Phoebe is singing.`)],-1),c[421]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡的公寓，菲比在唱歌。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/098.mp3`}),c[422]||=i(),c[423]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[424]||=i(` (singing) New York City has no power, and the milk is getting sour. But to me it is not scary, 'cause I stay away from dairy.... la la la, la la, la la... (she writes the lyrics down)`,-1),c[425]||=a(`blockquote`,null,[a(`p`,null,`（唱）纽约市没有电，牛奶变酸了。但对我来说这并不可怕，因为我远离奶制品……。拉拉，拉拉，拉拉……（她把歌词写下来）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/099.mp3`}),c[426]||=i(),c[427]||=a(`strong`,null,`Ross Geller:`,-1),c[428]||=i(` (to Joey) OK, here goes.`,-1),c[429]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊）好了，开始吧。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/100.mp3`}),c[430]||=i(),c[431]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[432]||=i(` Are you going to do it?`,-1),c[433]||=a(`blockquote`,null,[a(`p`,null,`你打算这么做吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/101.mp3`}),c[434]||=i(),c[435]||=a(`strong`,null,`Ross Geller:`,-1),c[436]||=i(` I'm going to do it.`,-1),c[437]||=a(`blockquote`,null,[a(`p`,null,`我要去做。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/102.mp3`}),c[438]||=i(),c[439]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[440]||=i(` Do you want any help?`,-1),c[441]||=a(`blockquote`,null,[a(`p`,null,`你需要帮忙吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/103.mp3`}),c[442]||=i(),c[443]||=a(`strong`,null,`Ross Geller:`,-1),c[444]||=i(` You come out there, you're a dead man.`,-1),c[445]||=a(`blockquote`,null,[a(`p`,null,`你出来，你就死定了。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/104.mp3`}),c[446]||=i(),c[447]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[448]||=i(` Good luck, man.`,-1),c[449]||=a(`blockquote`,null,[a(`p`,null,`祝你好运，伙计。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/105.mp3`}),c[450]||=i(),c[451]||=a(`strong`,null,`Ross Geller:`,-1),c[452]||=i(` Thanks. (Joey hugs him) OK.`,-1),c[453]||=a(`blockquote`,null,[a(`p`,null,`谢谢。（乔伊拥抱他）好的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/106.mp3`}),c[454]||=i(),c[455]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[456]||=i(` OK. (Ross goes out on the balcony to talk to Rachel)`,-1),c[457]||=a(`blockquote`,null,[a(`p`,null,`好的。（罗斯走到阳台上和瑞秋谈话）`)],-1),c[458]||=a(`p`,null,[a(`em`,null,`(Monica walks in, starts to go out on the balcony.)`)],-1),c[459]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡走进来，开始走到阳台上。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/107.mp3`}),c[460]||=i(),c[461]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[462]||=i(` Hey, where are you going?`,-1),c[463]||=a(`blockquote`,null,[a(`p`,null,`嘿，你要去哪里？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/108.mp3`}),c[464]||=i(),c[465]||=a(`strong`,null,`Monica Geller:`,-1),c[466]||=i(` Outside.`,-1),c[467]||=a(`blockquote`,null,[a(`p`,null,`外面。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/109.mp3`}),c[468]||=i(),c[469]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[470]||=i(` You can't go out there.`,-1),c[471]||=a(`blockquote`,null,[a(`p`,null,`你不能出去。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/110.mp3`}),c[472]||=i(),c[473]||=a(`strong`,null,`Monica Geller:`,-1),c[474]||=i(` Why not?`,-1),c[475]||=a(`blockquote`,null,[a(`p`,null,`为什么不呢？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/111.mp3`}),c[476]||=i(),c[477]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[478]||=i(` Because of... the reason.`,-1),c[479]||=a(`blockquote`,null,[a(`p`,null,`因为……原因。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/112.mp3`}),c[480]||=i(),c[481]||=a(`strong`,null,`Monica Geller:`,-1),c[482]||=i(` And that would be?`,-1),c[483]||=a(`blockquote`,null,[a(`p`,null,`那会是什么？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/113.mp3`}),c[484]||=i(),c[485]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[486]||=i(` I, um, can't tell you.`,-1),c[487]||=a(`blockquote`,null,[a(`p`,null,`我，嗯，不能告诉你。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/114.mp3`}),c[488]||=i(),c[489]||=a(`strong`,null,`Monica Geller:`,-1),c[490]||=i(` Joey, what's going on?`,-1),c[491]||=a(`blockquote`,null,[a(`p`,null,`乔伊，怎么了？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/115.mp3`}),c[492]||=i(),c[493]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[494]||=i(` OK, you've got to promise that you'll never, ever tell Ross that I told you.`,-1),c[495]||=a(`blockquote`,null,[a(`p`,null,`好吧，你必须保证你永远不会告诉罗斯我告诉过你的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/116.mp3`}),c[496]||=i(),c[497]||=a(`strong`,null,`Monica Geller:`,-1),c[498]||=i(` About what?`,-1),c[499]||=a(`blockquote`,null,[a(`p`,null,`关于什么？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/117.mp3`}),c[500]||=i(),c[501]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[502]||=i(` He's planning your birthday party.`,-1),c[503]||=a(`blockquote`,null,[a(`p`,null,`他在计划你的生日派对。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/118.mp3`}),c[504]||=i(),c[505]||=a(`strong`,null,`Monica Geller:`,-1),c[506]||=i(` Oh my God! I love him!`,-1),c[507]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！我爱他！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/119.mp3`}),c[508]||=i(),c[509]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[510]||=i(` (as Phoebe enters) You'd better act surprised.`,-1),c[511]||=a(`blockquote`,null,[a(`p`,null,`（菲比进来时）你最好装出惊讶的样子。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/120.mp3`}),c[512]||=i(),c[513]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[514]||=i(` About what?`,-1),c[515]||=a(`blockquote`,null,[a(`p`,null,`关于什么？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/121.mp3`}),c[516]||=i(),c[517]||=a(`strong`,null,`Monica Geller:`,-1),c[518]||=i(` My surprise party!`,-1),c[519]||=a(`blockquote`,null,[a(`p`,null,`我的惊喜派对！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/122.mp3`}),c[520]||=i(),c[521]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[522]||=i(` What surprise party?`,-1),c[523]||=a(`blockquote`,null,[a(`p`,null,`什么惊喜派对？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/123.mp3`}),c[524]||=i(),c[525]||=a(`strong`,null,`Monica Geller:`,-1),c[526]||=i(` Oh stop it. Joey already told me.`,-1),c[527]||=a(`blockquote`,null,[a(`p`,null,`哦，别说了。乔伊已经告诉我了。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/124.mp3`}),c[528]||=i(),c[529]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[530]||=i(` Well, he didn't tell me.`,-1),c[531]||=a(`blockquote`,null,[a(`p`,null,`嗯，他没有告诉我。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/125.mp3`}),c[532]||=i(),c[533]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[534]||=i(` Hey, don't look at me. This is Ross's thing.`,-1),c[535]||=a(`blockquote`,null,[a(`p`,null,`嘿，别看着我。这是罗斯的事。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/126.mp3`}),c[536]||=i(),c[537]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[538]||=i(` This is so typical. I'm always the last one to know everything.`,-1),c[539]||=a(`blockquote`,null,[a(`p`,null,`这太典型了。我总是最后一个知道一切的人。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/127.mp3`}),c[540]||=i(),c[541]||=a(`strong`,null,`Monica Geller:`,-1),c[542]||=i(` No, you are not. We tell you stuff.`,-1),c[543]||=a(`blockquote`,null,[a(`p`,null,`不，你不是。我们会告诉你的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/128.mp3`}),c[544]||=i(),c[545]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[546]||=i(` Yuh-huh! I was the last one to know when Chandler got bitten by the peacock at the zoo. I was the last one to know when you had a crush on Joey when he was moving in. (Monica gestures at Phoebe to shut up; Joey looks surprised but pleased) Looks like I was second to last.`,-1),c[547]||=a(`blockquote`,null,[a(`p`,null,`是啊！我是最后一个知道钱德勒在动物园被孔雀咬的人。我是最后一个知道你在乔伊搬进来的时候爱上他的人。（莫妮卡示意菲比闭嘴；乔伊看起来很惊讶但很高兴）看起来我是倒数第二。`)],-1),c[548]||=a(`hr`,null,null,-1),c[549]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's Balcony, Ross and Rachel are talking.`)],-1),c[550]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋的阳台，罗斯和瑞秋正在谈话。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/129.mp3`}),c[551]||=i(),c[552]||=a(`strong`,null,`Rachel Green:`,-1),c[553]||=i(` Hmmm... this is so nice.`,-1),c[554]||=a(`blockquote`,null,[a(`p`,null,`嗯……这太好了。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/130.mp3`}),c[555]||=i(),c[556]||=a(`strong`,null,`Ross Geller:`,-1),c[557]||=i(` OK, I have a question. Well, actually, it's not so much a question as.. more of a general wondering... ment.`,-1),c[558]||=a(`blockquote`,null,[a(`p`,null,`好的，我有个问题。事实上，这与其说是个问题不如说是。。更多的是一个普遍的疑问……是的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/131.mp3`}),c[559]||=i(),c[560]||=a(`strong`,null,`Rachel Green:`,-1),c[561]||=i(` OK.`,-1),c[562]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/132.mp3`}),c[563]||=i(),c[564]||=a(`strong`,null,`Ross Geller:`,-1),c[565]||=i(` OK. Here goes. For a while now, I've been wanting to, um....`,-1),c[566]||=a(`blockquote`,null,[a(`p`,null,`好的。来吧。一段时间以来，我一直想，嗯……。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/133.mp3`}),c[567]||=i(),c[568]||=a(`strong`,null,`Rachel Green:`,-1),c[569]||=i(` Ohhh!!!! (looking at something behind Ross)`,-1),c[570]||=a(`blockquote`,null,[a(`p`,null,`哦！！！！（看着罗斯身后的东西）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/134.mp3`}),c[571]||=i(),c[572]||=a(`strong`,null,`Ross Geller:`,-1),c[573]||=i(` Yes, yes, that's right...`,-1),c[574]||=a(`blockquote`,null,[a(`p`,null,`是的，是的，没错……`)],-1),r(p,{src:`/audio/friends/S01/S01E07/135.mp3`}),c[575]||=i(),c[576]||=a(`strong`,null,`Rachel Green:`,-1),c[577]||=i(` Oh, look at the little cat! (a small kitten is on the roof behind Ross)`,-1),c[578]||=a(`blockquote`,null,[a(`p`,null,`哦，看那只小猫！（一只小猫在罗斯身后的屋顶上）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/136.mp3`}),c[579]||=t(` <strong>Ross Geller:</strong> What? (the cat jumps on his shoulders) Ow!<blockquote><p>什么？（猫跳到他的肩膀上）噢！</p></blockquote><p>[Cut to inside. Monica, Joey and Phoebe are singing while outside, Ross and Rachel are trying to get the cat off of Ross&#39; shoulder.]</p><blockquote><p>[切到里面。莫妮卡、乔伊和菲比在唱歌，而在外面，罗斯和瑞秋正试图把猫从罗斯的肩膀上弄下来。]</p></blockquote><p>Monica, Joey, and **Phoebe Buffay: **(singing) I&#39;m on top of the world, looking down on creation and the only explanation I can find, is the wonders I&#39;ve found ever since...</p><blockquote><p>莫妮卡、乔伊和<strong>菲比·布菲：</strong>（唱）我站在世界之巅，俯视着创造，我能找到的唯一解释是，从那以后我发现的奇迹……</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Phoebe is holding the cat, Monica is treating the scratches on Ross&#39; back. Joey is holding the menorah over the wound.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，菲比抱着猫，莫妮卡在治疗罗斯背上的抓痕。乔伊在伤口上拿着手环。</em></p></blockquote>`,13),r(p,{src:`/audio/friends/S01/S01E07/137.mp3`}),c[580]||=i(),c[581]||=a(`strong`,null,`Monica Geller:`,-1),c[582]||=i(` (to Ross) This is just Bactine. It won't hurt.`,-1),c[583]||=a(`blockquote`,null,[a(`p`,null,`（对罗斯）这只是酒鬼。不会痛的。`)],-1),c[584]||=a(`p`,null,[a(`em`,null,`(Ross flinches in pain.)`)],-1),c[585]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯疼得直哆嗦。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/138.mp3`}),c[586]||=i(),c[587]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[588]||=i(` Sorry, that was wax.`,-1),c[589]||=a(`blockquote`,null,[a(`p`,null,`对不起，那是蜡。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/139.mp3`}),c[590]||=i(),c[591]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[592]||=i(` Oh, poor little Tooty is scared to death. We should find his owner.`,-1),c[593]||=a(`blockquote`,null,[a(`p`,null,`哦，可怜的小图蒂吓死了。我们应该找到他的主人。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/140.mp3`}),c[594]||=i(),c[595]||=a(`strong`,null,`Ross Geller:`,-1),c[596]||=i(` Why don't we just put 'poor little Tooty' out in the hall?`,-1),c[597]||=a(`blockquote`,null,[a(`p`,null,`我们为什么不把“可怜的小图蒂”放在大厅里？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/141.mp3`}),c[598]||=i(),c[599]||=a(`strong`,null,`Rachel Green:`,-1),c[600]||=i(` During a blackout? He'd get trampled!`,-1),c[601]||=a(`blockquote`,null,[a(`p`,null,`在停电期间？他会被踩死的！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/142.mp3`}),c[602]||=i(),c[603]||=a(`strong`,null,`Ross Geller:`,-1),c[604]||=i(` (nonchalantly) Yeah?`,-1),c[605]||=a(`blockquote`,null,[a(`p`,null,`（漫不经心地）是吗？`)],-1),c[606]||=a(`hr`,null,null,-1),c[607]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM vestibule.`)],-1),c[608]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM前厅。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/143.mp3`}),c[609]||=i(),c[610]||=a(`strong`,null,`Chandler Bing:`,-1),c[611]||=i(` You know, on second thought, gum would be perfection. (Jill gives him a stick of gum, and a strange look) 'Gum would be perfection'? 'Gum would be perfection.' Could have said 'gum would be nice,' or 'I'll have a stick,' but no, no, no, no. For me, gum is perfection. I loathe myself.`,-1),c[612]||=a(`blockquote`,null,[a(`p`,null,`你知道，再想一想，口香糖会是完美的。（吉尔给了他一根口香糖，奇怪地看了他一眼）“口香糖会很完美吗？”口香糖就是完美。可以说“口香糖很好”，或者“我要一根棍子”，但不，不，不，不。对我来说，口香糖就是完美。我讨厌我自己。`)],-1),c[613]||=a(`hr`,null,null,-1),c[614]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The hallway of Monica's building. Phoebe and Rachel are trying to find the cat's owner.`)],-1),c[615]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡大楼的走廊。菲比和瑞秋正在寻找猫的主人。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/144.mp3`}),c[616]||=i(),c[617]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[618]||=i(` (stops at a door) Oh no, the Mendels, they hate all living things, right?`,-1),c[619]||=a(`blockquote`,null,[a(`p`,null,`（停在门口）哦，不，孟德尔家族，他们讨厌所有的生物，对吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/145.mp3`}),c[620]||=i(),c[621]||=a(`strong`,null,`Rachel Green:`,-1),c[622]||=i(` Oh. (they knock at the next door, Mr. Heckles answers) Hi. We just found this cat and we're looking for the owner.`,-1),c[623]||=a(`blockquote`,null,[a(`p`,null,`哦。（他们在隔壁敲门，海克尔斯先生回答）嗨。我们刚找到这只猫，我们正在寻找它的主人。`)],-1),c[624]||=a(`p`,null,`Mr. Heckles: Er, yeah, it's mine.`,-1),c[625]||=a(`blockquote`,null,[a(`p`,null,`呃，是的，是我的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/146.mp3`}),c[626]||=i(),c[627]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[628]||=i(` (trying to hold back the struggling cat) He seems to hate you. Are you sure?`,-1),c[629]||=a(`blockquote`,null,[a(`p`,null,`（试图阻止那只挣扎的猫）他似乎恨你。你确定吗？`)],-1),c[630]||=a(`p`,null,`Mr. Heckles: Yeah, it's my cat. Give me my cat.`,-1),c[631]||=a(`blockquote`,null,[a(`p`,null,`是的，是我的猫。把我的猫给我。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/147.mp3`}),c[632]||=i(),c[633]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[634]||=i(` Wait a minute. What's his name?`,-1),c[635]||=a(`blockquote`,null,[a(`p`,null,`等一下。他叫什么名字？`)],-1),c[636]||=a(`p`,null,`Mr. Heckles: Ehhhh... B-Buttons.`,-1),c[637]||=a(`blockquote`,null,[a(`p`,null,`呃……B按钮。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/148.mp3`}),c[638]||=i(),c[639]||=a(`strong`,null,`Rachel Green:`,-1),c[640]||=i(` Bob Buttons?`,-1),c[641]||=a(`blockquote`,null,[a(`p`,null,`鲍勃·巴顿？`)],-1),c[642]||=a(`p`,null,`Mr. Heckles: Mmm. Bob Buttons. Here, Bob Buttons.`,-1),c[643]||=a(`blockquote`,null,[a(`p`,null,`嗯。鲍勃·巴顿。来，鲍勃·巴顿斯。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/149.mp3`}),c[644]||=t(` <strong>Phoebe Buffay:</strong> (the cat runs away from her) Oooh! You are a very bad man!<blockquote><p>（猫从她身边跑开）哦！你是个很坏的人！</p></blockquote><p>Mr. Heckles: (as Phoebe and Rachel leave) You owe me a cat.</p><blockquote><p>（菲比和瑞秋离开时）你欠我一只猫。</p></blockquote><hr><p>🎬 <em>Rachel has gone off on her own to look for the cat&#39;s owner.</em></p><blockquote><p>🎬 <em>瑞秋独自去寻找猫的主人。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S01/S01E07/150.mp3`}),c[645]||=i(),c[646]||=a(`strong`,null,`Rachel Green:`,-1),c[647]||=i(` Here, kitty-kitty. Here kitty-kitty. Where did you go, little kitty-kitty-kitty? Here kitty-kitty-kitty-kitty...`,-1),c[648]||=a(`blockquote`,null,[a(`p`,null,`给你，基蒂。凯蒂，凯蒂。你去哪了，小猫小猫小猫？这里是凯蒂凯蒂凯蒂凯蒂凯蒂……`)],-1),c[649]||=a(`p`,null,[a(`em`,null,`(While looking at the floor for the cat, Rachel runs into a pair of legs. She slowly gets up and sees a gorgeous Italian hunk holding the cat. Who, by the way, you'll hate very, very soon. The man. Not the cat.)`)],-1),c[650]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（当瑞秋在地板上寻找猫的时候，她撞到了一对腿。她慢慢地站起来，看到一个漂亮的意大利帅哥抱着猫。顺便说一句，你很快就会讨厌他。那个男人。不是猫。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/151.mp3`}),c[651]||=i(),c[652]||=a(`strong`,null,`Paolo:`,-1),c[653]||=i(` (something Italian)`,-1),c[654]||=a(`blockquote`,null,[a(`p`,null,`（意大利语）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/152.mp3`}),c[655]||=i(),c[656]||=a(`strong`,null,`Rachel Green:`,-1),c[657]||=i(` Wow. (she exhales in amazement, blowing the candle out)`,-1),c[658]||=a(`blockquote`,null,[a(`p`,null,`哇。（她惊讶地呼气，吹灭了蜡烛）`)],-1),c[659]||=a(`hr`,null,null,-1),c[660]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Ross, Monica, and Joey are playing Monopoly.`)],-1),c[661]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋、罗斯、莫妮卡和乔伊在玩大富翁游戏。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/153.mp3`}),c[662]||=i(),c[663]||=a(`strong`,null,`Ross Geller:`,-1),c[664]||=i(` (rolling) Lucky sixes....`,-1),c[665]||=a(`blockquote`,null,[a(`p`,null,`（滚动）幸运六……。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/154.mp3`}),c[666]||=i(),c[667]||=a(`strong`,null,`Rachel Green:`,-1),c[668]||=i(` (entering with Paolo, arm in arm) Everybody, this is Paolo. Paolo, I want you to meet my friends. This is Monica.`,-1),c[669]||=a(`blockquote`,null,[a(`p`,null,`（和保罗手挽手走进来）大家，这是保罗。保罗，我想让你见见我的朋友。我是莫妮卡。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/155.mp3`}),c[670]||=i(),c[671]||=a(`strong`,null,`Monica Geller:`,-1),c[672]||=i(` (smitten) Hi!`,-1),c[673]||=a(`blockquote`,null,[a(`p`,null,`（被迷住了）嗨！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/156.mp3`}),c[674]||=i(),c[675]||=a(`strong`,null,`Rachel Green:`,-1),c[676]||=i(` And Joey....`,-1),c[677]||=a(`blockquote`,null,[a(`p`,null,`还有乔伊……。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/157.mp3`}),c[678]||=i(),c[679]||=a(`strong`,null,`Monica Geller:`,-1),c[680]||=i(` Hi!`,-1),c[681]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/158.mp3`}),c[682]||=i(),c[683]||=a(`strong`,null,`Rachel Green:`,-1),c[684]||=i(` And Ross.`,-1),c[685]||=a(`blockquote`,null,[a(`p`,null,`还有罗斯。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/159.mp3`}),c[686]||=i(),c[687]||=a(`strong`,null,`Monica Geller:`,-1),c[688]||=i(` Hi!`,-1),c[689]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/160.mp3`}),c[690]||=i(),c[691]||=a(`strong`,null,`Paolo:`,-1),c[692]||=i(` (something in Italian)`,-1),c[693]||=a(`blockquote`,null,[a(`p`,null,`（意大利语）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/161.mp3`}),c[694]||=i(),c[695]||=a(`strong`,null,`Rachel Green:`,-1),c[696]||=i(` (proudly) He doesn't speak much English.`,-1),c[697]||=a(`blockquote`,null,[a(`p`,null,`（自豪地）他英语说得不多。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/162.mp3`}),c[698]||=i(),c[699]||=a(`strong`,null,`Paolo:`,-1),c[700]||=i(` (pointing at game) Monopoly!`,-1),c[701]||=a(`blockquote`,null,[a(`p`,null,`（指着游戏）垄断！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/163.mp3`}),c[702]||=i(),c[703]||=a(`strong`,null,`Rachel Green:`,-1),c[704]||=i(` Look at that!`,-1),c[705]||=a(`blockquote`,null,[a(`p`,null,`看那个！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/164.mp3`}),c[706]||=i(),c[707]||=a(`strong`,null,`Ross Geller:`,-1),c[708]||=i(` (jealous) So, um... where did Paolo come from?`,-1),c[709]||=a(`blockquote`,null,[a(`p`,null,`（嫉妒）所以，嗯……保罗来自哪里？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/165.mp3`}),c[710]||=i(),c[711]||=a(`strong`,null,`Rachel Green:`,-1),c[712]||=i(` Oh... Italy, I think.`,-1),c[713]||=a(`blockquote`,null,[a(`p`,null,`哦……我想是意大利。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/166.mp3`}),c[714]||=i(),c[715]||=a(`strong`,null,`Ross Geller:`,-1),c[716]||=i(` No, I mean tonight, in the building. Suddenly. Into our lives.`,-1),c[717]||=a(`blockquote`,null,[a(`p`,null,`不，我是说今晚，在大楼里。突然。进入我们的生活。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/167.mp3`}),c[718]||=i(),c[719]||=a(`strong`,null,`Rachel Green:`,-1),c[720]||=i(` Well, the cat... the cat turned out to be Paolo's cat!`,-1),c[721]||=a(`blockquote`,null,[a(`p`,null,`嗯，那只猫……那只猫原来是保罗的猫！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/168.mp3`}),c[722]||=i(),c[723]||=a(`strong`,null,`Ross Geller:`,-1),c[724]||=i(` That, that is funny... (to Joey).... and Rachel keeps touching him.`,-1),c[725]||=a(`blockquote`,null,[a(`p`,null,`那，那很有趣……（对乔伊）……。瑞秋一直摸他。`)],-1),c[726]||=a(`p`,null,[a(`em`,null,`(Phoebe enters.)`)],-1),c[727]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（菲比进来了。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/169.mp3`}),c[728]||=i(),c[729]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[730]||=i(` Alright. I looked all over the building and I couldn't find the kitty anywhere.`,-1),c[731]||=a(`blockquote`,null,[a(`p`,null,`好的。我找遍了整栋楼，到处都找不到那只小猫。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/170.mp3`}),c[732]||=i(),c[733]||=a(`strong`,null,`Rachel Green:`,-1),c[734]||=i(` Oh, I found him. He was Paolo's cat.`,-1),c[735]||=a(`blockquote`,null,[a(`p`,null,`哦，我找到他了。他是保罗的猫。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/171.mp3`}),c[736]||=i(),c[737]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[738]||=i(` Ah! Well! There you go! Last to know again! And I'm guessing... since nobody told me... this is Paolo.`,-1),c[739]||=a(`blockquote`,null,[a(`p`,null,`啊！好！好了！最后才知道！我猜……既然没人告诉我……我是保罗。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/172.mp3`}),c[740]||=i(),c[741]||=a(`strong`,null,`Rachel Green:`,-1),c[742]||=i(` Ah, Paolo, this is Phoebe.`,-1),c[743]||=a(`blockquote`,null,[a(`p`,null,`啊，保罗，这是菲比。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/173.mp3`}),c[744]||=i(),c[745]||=a(`strong`,null,`Paolo:`,-1),c[746]||=i(` (something in Italian, he is apparently attracted to Phoebe)`,-1),c[747]||=a(`blockquote`,null,[a(`p`,null,`（意大利语，他显然被菲比吸引了）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/174.mp3`}),c[748]||=i(),c[749]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[750]||=i(` (smiling) You betcha!`,-1),c[751]||=a(`blockquote`,null,[a(`p`,null,`（微笑）没错！`)],-1),c[752]||=a(`hr`,null,null,-1),c[753]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM vestibule.`)],-1),c[754]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`ATM前厅。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/175.mp3`}),c[755]||=i(),c[756]||=a(`strong`,null,`Chandler Bing:`,-1),c[757]||=i(` (chewing gum) Ah, let's see. What next? Blow a bubble. A bubble's good. It's got a... boyish charm, it's impish. Here we go.`,-1),c[758]||=a(`blockquote`,null,[a(`p`,null,`（嚼口香糖）啊，让我想想。接下来呢？吹泡泡。泡沫很好。它有一个……孩子气的魅力，很顽皮。我们开始吧。`)],-1),c[759]||=a(`p`,null,[a(`em`,null,`(Chandler waits until Jill is looking, then starts to blow a bubble. But instead of blow one, he accidentally spits the gum out of his mouth and hits the wall.)`)],-1),c[760]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒等着吉尔看，然后开始吹泡泡。但他没有吹泡泡，而是不小心把口香糖吐了出来，撞到了墙上。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/176.mp3`}),c[761]||=i(),c[762]||=a(`strong`,null,`Chandler Bing:`,-1),c[763]||=i(` Nice going, imp. OK, it's OK. All I need to do is reach over and put it in my mouth. (Chandler slyly grabs the gum from the wall and slides it back in his mouth.)`,-1),c[764]||=a(`blockquote`,null,[a(`p`,null,`干得好，小鬼。好的，没关系。我所需要做的就是伸手把它放进我的嘴里。（钱德勒狡猾地从墙上抓起口香糖，把它放回嘴里。）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/177.mp3`}),c[765]||=i(),c[766]||=a(`strong`,null,`Chandler Bing:`,-1),c[767]||=i(` Good save! We're back on track, and I'm... (grimacing) ..chewing someone else's gum. This is not my gum. Oh my God! Oh my God! And now you're choking.`,-1),c[768]||=a(`blockquote`,null,[a(`p`,null,`好扑救！我们回到了正轨，我……（做鬼脸）…嚼别人的口香糖。这不是我的口香糖。哦，我的上帝！哦，我的上帝！现在你窒息了。`)],-1),c[769]||=a(`p`,null,[a(`em`,null,`(Chandler starts to choke.)`)],-1),c[770]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒开始哽咽。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/178.mp3`}),c[771]||=i(),c[772]||=a(`strong`,null,`Jill:`,-1),c[773]||=i(` Are you alright?`,-1),c[774]||=a(`blockquote`,null,[a(`p`,null,`你没事吧？`)],-1),c[775]||=a(`p`,null,[a(`em`,null,`(Chandler tries to save face and makes the 'OK' sign with his hands, while obviously unable to breathe.)`)],-1),c[776]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒试图挽回面子，用手做出“OK”的手势，但显然无法呼吸。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/179.mp3`}),c[777]||=i(),c[778]||=a(`strong`,null,`Jill:`,-1),c[779]||=i(` My God, you're choking! (she runs over and gives him the Heimlich, the gum flies from his mouth) That better?`,-1),c[780]||=a(`blockquote`,null,[a(`p`,null,`天哪，你噎住了！（她跑过去给他海姆利克，口香糖从他嘴里飞出来）那更好吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/180.mp3`}),c[781]||=i(),c[782]||=a(`strong`,null,`Chandler Bing:`,-1),c[783]||=i(` (gasping) Yes... thank you. That was... that was....`,-1),c[784]||=a(`blockquote`,null,[a(`p`,null,`（喘息）是的……非常感谢。那是……那是……。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/181.mp3`}),c[785]||=i(),c[786]||=a(`strong`,null,`Jill:`,-1),c[787]||=i(` Perfection?`,-1),c[788]||=a(`blockquote`,null,[a(`p`,null,`完美吗？`)],-1),c[789]||=a(`hr`,null,null,-1),c[790]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Rachel and Paolo are at the window. Ross and Joey are watching disgustedly.`)],-1),c[791]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，瑞秋和保罗在窗口。罗斯和乔伊厌恶地看着。`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/182.mp3`}),c[792]||=i(),c[793]||=a(`strong`,null,`Paolo:`,-1),c[794]||=i(` (something romantic in Italian about Rachel and the stars)`,-1),c[795]||=a(`blockquote`,null,[a(`p`,null,`（用意大利语讲瑞秋和明星们的浪漫）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/183.mp3`}),c[796]||=i(),c[797]||=a(`strong`,null,`Ross Geller:`,-1),c[798]||=i(` (mocking Paolo) Blah blah blah, blah blah blah... blah blaaaaaah....`,-1),c[799]||=a(`blockquote`,null,[a(`p`,null,`（嘲笑保罗）诸如此类，诸如此类……诸如此类……。`)],-1),c[800]||=a(`p`,null,[a(`em`,null,`(Rachel walks away from Paolo, laughing.)`)],-1),c[801]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋笑着从保罗身边走开。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/184.mp3`}),c[802]||=i(),c[803]||=a(`strong`,null,`Ross Geller:`,-1),c[804]||=i(` Wha-What did he say that was so funny?`,-1),c[805]||=a(`blockquote`,null,[a(`p`,null,`他说了什么那么好笑？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/185.mp3`}),c[806]||=i(),c[807]||=a(`strong`,null,`Rachel Green:`,-1),c[808]||=i(` I have absolutely no idea.`,-1),c[809]||=a(`blockquote`,null,[a(`p`,null,`我完全不知道。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/186.mp3`}),c[810]||=i(),c[811]||=a(`strong`,null,`Ross Geller:`,-1),c[812]||=i(` That's... that's classic.`,-1),c[813]||=a(`blockquote`,null,[a(`p`,null,`那是……这很经典。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/187.mp3`}),c[814]||=i(),c[815]||=a(`strong`,null,`Rachel Green:`,-1),c[816]||=i(` (to Monica and Phoebe) Oh my God, you guys, what am I doing? What am I doing? This is so un-me!`,-1),c[817]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡和菲比）哦，天哪，你们这些家伙，我在干什么？我在干什么？这太不适合我了！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/188.mp3`}),c[818]||=i(),c[819]||=a(`strong`,null,`Monica Geller:`,-1),c[820]||=i(` If you want, I'll do it.`,-1),c[821]||=a(`blockquote`,null,[a(`p`,null,`如果你愿意，我会做的。`)],-1),c[822]||=a(`p`,null,[a(`em`,null,`(Ross looks at Joey.)`)],-1),c[823]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯看着乔伊。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/189.mp3`}),c[824]||=i(),c[825]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[826]||=i(` I know, I just want to bite his bottom lip. (Rachel looks at her) But I won't.`,-1),c[827]||=a(`blockquote`,null,[a(`p`,null,`我知道，我只想咬他的下唇。（瑞秋看着她）但我不会。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/190.mp3`}),c[828]||=i(),c[829]||=a(`strong`,null,`Rachel Green:`,-1),c[830]||=i(` God, the first time he smiled at me... those three seconds were more exciting than three weeks in Bermuda with Barry.`,-1),c[831]||=a(`blockquote`,null,[a(`p`,null,`天啊，他第一次对我微笑……这三秒钟比巴里在百慕大的三个星期更令人兴奋。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/191.mp3`}),c[832]||=i(),c[833]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[834]||=i(` You know, did you ride mopeds? 'Cause I've heard... (they stare at her)... oh, I see... it's not about that right now. OK.`,-1),c[835]||=a(`blockquote`,null,[a(`p`,null,`你知道，你骑过轻便摩托车吗？”因为我听说……（他们盯着她）……哦，我明白了……现在不是这个问题。好啊`)],-1),r(p,{src:`/audio/friends/S01/S01E07/192.mp3`}),c[836]||=i(),c[837]||=a(`strong`,null,`Rachel Green:`,-1),c[838]||=i(` Y'know, I know it's totally superficial and we have absolutely nothing in common, and we don't even speak the same language but Goooooooddddddd....`,-1),c[839]||=a(`blockquote`,null,[a(`p`,null,`你知道，我知道这完全是肤浅的，我们完全没有共同点，我们甚至不会说同一种语言，只是咕噜咕噜……。`)],-1),c[840]||=a(`p`,null,`[Cut to the other side of the apartment, Ross has gone over to straighten things out with Paolo.]`,-1),c[841]||=a(`blockquote`,null,[a(`p`,null,`[切到公寓的另一边，罗斯已经过去和保罗解决问题了。]`)],-1),r(p,{src:`/audio/friends/S01/S01E07/193.mp3`}),c[842]||=i(),c[843]||=a(`strong`,null,`Ross Geller:`,-1),c[844]||=i(` Paolo. Hi.`,-1),c[845]||=a(`blockquote`,null,[a(`p`,null,`保罗。你好`)],-1),r(p,{src:`/audio/friends/S01/S01E07/194.mp3`}),c[846]||=i(),c[847]||=a(`strong`,null,`Paolo:`,-1),c[848]||=i(` Ross!`,-1),c[849]||=a(`blockquote`,null,[a(`p`,null,`罗斯！`)],-1),c[850]||=a(`p`,null,[a(`em`,null,`(Ross notices that Paolo is standing on a step, which makes him taller. Ross gets up on the same step so he can look down at Paolo.)`)],-1),c[851]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯注意到保罗站在台阶上，这使他更高了。罗斯站在同一台阶上，这样他就可以俯视保罗。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/195.mp3`}),c[852]||=i(),c[853]||=a(`strong`,null,`Ross Geller:`,-1),c[854]||=i(` Listen. Um, listen. Something you should... know... um, Rachel and I... we're kind of a thing.`,-1),c[855]||=a(`blockquote`,null,[a(`p`,null,`听着。嗯，听着。有些事你应该……知道……嗯，瑞秋和我……我们是一种东西。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/196.mp3`}),c[856]||=i(),c[857]||=a(`strong`,null,`Paolo:`,-1),c[858]||=i(` Thing?`,-1),c[859]||=a(`blockquote`,null,[a(`p`,null,`什么事？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/197.mp3`}),c[860]||=i(),c[861]||=a(`strong`,null,`Ross Geller:`,-1),c[862]||=i(` Thing, yes. Thing.`,-1),c[863]||=a(`blockquote`,null,[a(`p`,null,`是的。事情`)],-1),r(p,{src:`/audio/friends/S01/S01E07/198.mp3`}),c[864]||=i(),c[865]||=a(`strong`,null,`Paolo:`,-1),c[866]||=i(` Ah, you... have the sex?`,-1),c[867]||=a(`blockquote`,null,[a(`p`,null,`啊，你……做爱？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/199.mp3`}),c[868]||=i(),c[869]||=a(`strong`,null,`Ross Geller:`,-1),c[870]||=i(` No, no, no. Technically the... sex is not... being had, but that's... see, that's not the point. See, um, the point is that... Rachel and I should be, er, together. You know, and if you get in the.... um...`,-1),c[871]||=a(`blockquote`,null,[a(`p`,null,`不，不，不。从技术上来说……性不是……被拥有，但那是……看，这不是重点。看，嗯，重点是……瑞秋和我应该在一起。你知道，如果你进入……。嗯……`)],-1),r(p,{src:`/audio/friends/S01/S01E07/200.mp3`}),c[872]||=i(),c[873]||=a(`strong`,null,`Paolo:`,-1),c[874]||=i(` Bed?`,-1),c[875]||=a(`blockquote`,null,[a(`p`,null,`床？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/201.mp3`}),c[876]||=i(),c[877]||=a(`strong`,null,`Ross Geller:`,-1),c[878]||=i(` No, no, that's not where I was going. Er, if you get in the... way, of us becoming a thing, then I would be, well, very sad.`,-1),c[879]||=a(`blockquote`,null,[a(`p`,null,`不，不，那不是我要去的地方。呃，如果你进入……这样的话，如果我们成为一件事，那么我会非常难过。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/202.mp3`}),c[880]||=i(),c[881]||=a(`strong`,null,`Paolo:`,-1),c[882]||=i(` Oh!`,-1),c[883]||=a(`blockquote`,null,[a(`p`,null,`哦！`)],-1),r(p,{src:`/audio/friends/S01/S01E07/203.mp3`}),c[884]||=i(),c[885]||=a(`strong`,null,`Ross Geller:`,-1),c[886]||=i(` Yeah! Se vice?`,-1),c[887]||=a(`blockquote`,null,[a(`p`,null,`是啊！邪恶？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/204.mp3`}),c[888]||=i(),c[889]||=a(`strong`,null,`Paolo:`,-1),c[890]||=i(` Si.`,-1),c[891]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/205.mp3`}),c[892]||=i(),c[893]||=a(`strong`,null,`Ross Geller:`,-1),c[894]||=i(` So you do know a little English.`,-1),c[895]||=a(`blockquote`,null,[a(`p`,null,`所以你确实懂一点英语。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/206.mp3`}),c[896]||=i(),c[897]||=a(`strong`,null,`Paolo:`,-1),c[898]||=i(` Poco... a leetle.`,-1),c[899]||=a(`blockquote`,null,[a(`p`,null,`波科……韭菜。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/207.mp3`}),c[900]||=i(),c[901]||=a(`strong`,null,`Ross Geller:`,-1),c[902]||=i(` Do you know the word crapweasel?`,-1),c[903]||=a(`blockquote`,null,[a(`p`,null,`你知道“黄鼠狼”这个词吗？`)],-1),r(p,{src:`/audio/friends/S01/S01E07/208.mp3`}),c[904]||=i(),c[905]||=a(`strong`,null,`Paolo:`,-1),c[906]||=i(` No.`,-1),c[907]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/209.mp3`}),c[908]||=t(` <strong>Ross Geller:</strong> That&#39;s funny, because you know, you are a huge crapweasel!<blockquote><p>那很有趣，因为你知道，你是一只巨大的黄鼠狼！</p></blockquote><p><em>(They hug.)</em></p><blockquote><p><em>（他们拥抱。）</em></p></blockquote><hr><p>🎬 <em>ATM vestibule, Chandler and Jill are sitting below the counter with two pens dangling from their chains in front of them. Jill is showing Chandler how to swing the pen around his head.</em></p><blockquote><p>🎬 <em>自动取款机前厅，钱德勒和吉尔坐在柜台下面，两支钢笔悬挂在他们面前的链子上。吉尔正在教钱德勒如何在他的头上挥动钢笔。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S01/S01E07/210.mp3`}),c[909]||=i(),c[910]||=a(`strong`,null,`Jill:`,-1),c[911]||=i(` Chandler, we've been here for an hour doing this! Now watch, it's easy.`,-1),c[912]||=a(`blockquote`,null,[a(`p`,null,`钱德勒，我们已经在这里做了一个小时了！现在看，这很容易。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/211.mp3`}),c[913]||=i(),c[914]||=a(`strong`,null,`Chandler Bing:`,-1),c[915]||=i(` OK.`,-1),c[916]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/212.mp3`}),c[917]||=i(),c[918]||=a(`strong`,null,`Jill:`,-1),c[919]||=i(` Ready? (she swings the pen around her head in a circle)`,-1),c[920]||=a(`blockquote`,null,[a(`p`,null,`准备好了吗？（她把笔绕着头转了一圈）`)],-1),c[921]||=a(`p`,null,[a(`em`,null,`(Chandler tries to do the same thing but the pen hits him in the head.)`)],-1),c[922]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒试着做同样的事情，但那支笔击中了他的头部。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/213.mp3`}),c[923]||=t(` <strong>Jill:</strong> No, you&#39;ve got to whip it.<blockquote><p>不，你必须鞭打它。</p></blockquote><p><em>(He swings the pen hard, and it snaps back and almost hits him again.)</em></p><blockquote><p><em>（他使劲挥动笔，笔猛地弹了回来，差点又打到他。）</em></p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, the gang is all sitting around the table.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，一伙人围着桌子坐着。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S01/S01E07/214.mp3`}),c[924]||=i(),c[925]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[926]||=i(` Oh, look look look. The last candle's about to burn out. 10, 9, 8, 7... (time lapse)... negative 46, negative 47, negative 48.... (someone blows it out, the room gets completely dark)`,-1),c[927]||=a(`blockquote`,null,[a(`p`,null,`哦，看。最后一支蜡烛就要燃尽了。10, 9, 8, 7... （时间流逝）……负46，负47，负48……。（有人把它吹灭了，房间里一片漆黑）`)],-1),r(p,{src:`/audio/friends/S01/S01E07/215.mp3`}),c[928]||=i(),c[929]||=a(`strong`,null,`Ross Geller:`,-1),c[930]||=i(` Thank you.`,-1),c[931]||=a(`blockquote`,null,[a(`p`,null,`谢谢。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/216.mp3`}),c[932]||=i(),c[933]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[934]||=i(` Thanks.`,-1),c[935]||=a(`blockquote`,null,[a(`p`,null,`谢谢。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/217.mp3`}),c[936]||=i(),c[937]||=a(`strong`,null,`Ross Geller:`,-1),c[938]||=i(` Kinda... spooky without any lights.`,-1),c[939]||=a(`blockquote`,null,[a(`p`,null,`有点……没有灯光的幽灵。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/218.mp3`}),c[940]||=i(),c[941]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[942]||=i(` (does a maniacal laugh) Bwah-hah-hah!`,-1),c[943]||=a(`blockquote`,null,[a(`p`,null,`（狂笑）哈哈哈！`)],-1),c[944]||=a(`p`,null,[a(`em`,null,`(Everyone starts to imitate him.)`)],-1),c[945]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（每个人都开始模仿他。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/219.mp3`}),c[946]||=i(),c[947]||=a(`strong`,null,`Ross Geller:`,-1),c[948]||=i(` OK, guys, guys? I have the definitive one. Mwwwooooo-hah-hah...`,-1),c[949]||=a(`blockquote`,null,[a(`p`,null,`好的，伙计们，伙计们？我有一个确定的。哈哈哈……`)],-1),c[950]||=a(`p`,null,[a(`em`,null,`(The lights come back on, and Rachel and Paolo are making out. Ross clutches his chest.)`)],-1),c[951]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（灯又亮了，瑞秋和保罗亲热起来。罗斯紧紧抓住他的胸部。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/220.mp3`}),c[952]||=i(),c[953]||=a(`strong`,null,`Ross Geller:`,-1),c[954]||=i(` Oh.. oh... oh.`,-1),c[955]||=a(`blockquote`,null,[a(`p`,null,`哦。。哦哦`)],-1),r(p,{src:`/audio/friends/S01/S01E07/221.mp3`}),c[956]||=t(` <strong>Joey Tribbiani:</strong> Hey Ross. This probably isn&#39;t the best time to bring it up, but you have to throw a party for Monica.<blockquote><p>嘿，罗斯。现在可能不是提这事的最佳时机，但你得为莫妮卡开个派对。</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>ATM vestibule, the power has come back on.</em></p><blockquote><p>🎬 <em>ATM前厅，电源又接通了。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S01/S01E07/222.mp3`}),c[957]||=i(),c[958]||=a(`strong`,null,`Jill:`,-1),c[959]||=i(` Well, this has been fun.`,-1),c[960]||=a(`blockquote`,null,[a(`p`,null,`嗯，这很有趣。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/223.mp3`}),c[961]||=i(),c[962]||=a(`strong`,null,`Chandler Bing:`,-1),c[963]||=i(` Yes. Yes, thanks for letting me use your phone... and for saving my life.`,-1),c[964]||=a(`blockquote`,null,[a(`p`,null,`是的。是的，谢谢你让我用你的电话……为了救我的命。`)],-1),r(p,{src:`/audio/friends/S01/S01E07/224.mp3`}),c[965]||=i(),c[966]||=a(`strong`,null,`Jill:`,-1),c[967]||=i(` Well, goodbye Chandler. I had a great blackout. (she kisses him on the cheek) See ya.`,-1),c[968]||=a(`blockquote`,null,[a(`p`,null,`好吧，再见，钱德勒。我大昏迷了。（她吻了吻他的脸颊）再见。`)],-1),c[969]||=a(`p`,null,[a(`em`,null,`(She leaves. Chandler presses his face to the glass door after her, stroking the window lovingly. He then turns to the security camera and starts talking to it.)`)],-1),c[970]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她离开了。钱德勒在她身后把脸贴在玻璃门上，慈爱地抚摸着窗户。然后他转向安全摄像头，开始和它说话。）`)])],-1),r(p,{src:`/audio/friends/S01/S01E07/225.mp3`}),c[971]||=i(),c[972]||=a(`strong`,null,`Chandler Bing:`,-1),c[973]||=i(` Hi, um, I'm account number 7143457. And, uh, I don't know if you got any of that, but I would really like a copy of the tape.`,-1),c[974]||=a(`blockquote`,null,[a(`p`,null,`嗨，嗯，我的账号是7143457。呃，我不知道你有没有这些，但我真的想要一份录音带。`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};